import{_ as t,o as a,c as i,a5 as o}from"./chunks/framework.QnCkLuYX.js";const n="/assets/timeline-and-timing.CEsAxc1v.png",s="/assets/timing-editor.CvUHyXXg.png",m=JSON.parse('{"title":"Reviewing Subtitles","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/03-reviewing-subtitles.md","filePath":"en_US/03-reviewing-subtitles.md"}'),r={name:"en_US/03-reviewing-subtitles.md"};function l(d,e,c,h,u,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="reviewing-subtitles" tabindex="-1">Reviewing Subtitles <a class="header-anchor" href="#reviewing-subtitles" aria-label="Permalink to &quot;Reviewing Subtitles&quot;">​</a></h1><p>Edit text and timing while keeping the grid, video, timeline, and current selection synchronized.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Navigate and select subtitle rows and cells.</li><li>Edit, copy, paste, and fill source or translation text.</li><li>Play the assigned video and follow subtitle timing.</li><li>Adjust timing safely and undo changes.</li></ul><h2 id="browse-and-select-subtitles" tabindex="-1">Browse and select subtitles <a class="header-anchor" href="#browse-and-select-subtitles" aria-label="Permalink to &quot;Browse and select subtitles&quot;">​</a></h2><p>Click a cell to focus it. Drag across cells or use row-selection controls to select a range. The current row is reflected in the grid, timeline, and playback controls.</p><p>Use the episode selector to move between episodes. Filters may hide rows; the status summary shows visible and selected counts.</p><h2 id="edit-source-and-translation-text" tabindex="-1">Edit source and translation text <a class="header-anchor" href="#edit-source-and-translation-text" aria-label="Permalink to &quot;Edit source and translation text&quot;">​</a></h2><p>Double-click or press <code>Enter</code> to edit a text cell. Confirm with <code>Enter</code> or click elsewhere; press <code>Esc</code> to cancel the active edit.</p><p>Source and translation cells are editable. Calculated fields such as character count and CPS update automatically and should not be edited directly.</p><p>For multiline subtitle text, GridSubStudio preserves real line breaks and the subtitle format&#39;s line-break representation during import/export.</p><h2 id="copy-paste-and-fill-content" tabindex="-1">Copy, paste, and fill content <a class="header-anchor" href="#copy-paste-and-fill-content" aria-label="Permalink to &quot;Copy, paste, and fill content&quot;">​</a></h2><p>Use standard <code>Ctrl+C</code> (<code>Command+C</code> on macOS), <code>Ctrl+V</code> (<code>Command+V</code> on macOS), and <code>Delete</code> operations. Pasting a rectangular block fills the corresponding grid range. Review the selection before a large paste, especially when filters are active.</p><p>Undo immediately if pasted data is shifted or affects unintended rows.</p><h2 id="play-and-switch-video" tabindex="-1">Play and switch video <a class="header-anchor" href="#play-and-switch-video" aria-label="Permalink to &quot;Play and switch video&quot;">​</a></h2><p>Select a video from the video selector, then use <strong>Play</strong>, <code>Space</code>, <strong>Prev</strong>, and <strong>Next</strong>. Playback rate buttons change review speed without changing subtitle timing.</p><p>The active episode determines which timeline rows and video are shown. If a video is missing, subtitle editing remains available.</p><h2 id="use-the-timeline" tabindex="-1">Use the timeline <a class="header-anchor" href="#use-the-timeline" aria-label="Permalink to &quot;Use the timeline&quot;">​</a></h2><p><img src="'+n+'" alt="Timeline range, playback controls, speed buttons, and zoom slider"></p><p>Click or drag on the timeline to seek. Click a subtitle range to focus its row. Use the zoom buttons or slider to inspect crowded timing ranges.</p><p>Timeline focus follows the real grid selection; selecting a row should update both the row highlight and active range.</p><h2 id="adjust-start-and-end-times" tabindex="-1">Adjust start and end times <a class="header-anchor" href="#adjust-start-and-end-times" aria-label="Permalink to &quot;Adjust start and end times&quot;">​</a></h2><p>Focus a subtitle row and click <strong>Adjust Time</strong>.</p><p><img src="'+s+'" alt="Subtitle timing editor with start, end, duration, and apply controls"></p><p>Edit start/end values or adjust the range on the timeline. GridSubStudio checks invalid ranges, ordering, and overlaps before applying. A warning requires confirmation; it does not silently change neighboring subtitles.</p><h2 id="navigate-subtitles-and-episodes" tabindex="-1">Navigate subtitles and episodes <a class="header-anchor" href="#navigate-subtitles-and-episodes" aria-label="Permalink to &quot;Navigate subtitles and episodes&quot;">​</a></h2><ul><li><code>Alt+Up</code> / <code>Alt+Down</code>: previous or next subtitle.</li><li><strong>Prev</strong> / <strong>Next</strong> in playback controls: move between videos where available.</li><li>Click validation counters to jump to the next matching issue.</li><li>Repeated navigation wraps through the applicable set.</li></ul><h2 id="undo-and-redo" tabindex="-1">Undo and redo <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Undo and redo&quot;">​</a></h2><p>Use <code>Ctrl+Z</code> (<code>Command+Z</code> on macOS) and <code>Ctrl+Y</code> (<code>Command+Y</code> on macOS) (<code>Ctrl+Shift+Z</code> (<code>Command+Shift+Z</code> on macOS) also works for redo). Text, timing, and row operations participate in the workspace history. Saving does not erase the ability to compare the saved and current state, but reopening starts from persisted data.</p><p>Using subtitle <strong>Whole Replacement</strong> to rebuild matched episodes clears the previous undo and redo history, although unmatched episodes remain in the workspace.</p><h2 id="reset-the-workspace-view" tabindex="-1">Reset the workspace view <a class="header-anchor" href="#reset-the-workspace-view" aria-label="Permalink to &quot;Reset the workspace view&quot;">​</a></h2><p>Use <strong>Reset View</strong> to restore the default column layout and panel proportions. This changes presentation only; it does not remove subtitle data.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Selection and timeline disagree:</strong> click the intended row once, then verify the active timeline range.</li><li><strong>Playback controls are disabled:</strong> select a row/video and confirm the episode has an available video.</li><li><strong>Timing cannot be applied:</strong> correct invalid start/end values or explicitly confirm the warning.</li><li><strong>A paste affected the wrong rows:</strong> undo, clear filters if necessary, and repeat with a verified selection.</li></ul>',34)])])}const b=t(r,[["render",l]]);export{m as __pageData,b as default};
